export interface FacultyPublicationRecord { department: string; facultyName: string; details: Record<string, string>; }

const compressedPublicationData = "";

export async function loadFacultyPublicationData(): Promise<FacultyPublicationRecord[]> {
  const bytes = Uint8Array.from(atob(compressedPublicationData), character => character.charCodeAt(0));
  const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream("gzip"));
  return await new Response(stream).json() as FacultyPublicationRecord[];
}

const normalizeName = (value: string) => value.toLowerCase().replace(/^(dr|prof|mr|mrs|ms|smt|sri)(?:\.|\s+)/, "").replace(/[^a-z0-9]/g, "");
const facultyNameTokens = (value: string) => value.toLowerCase().replace(/^(dr|prof|mr|mrs|ms|smt|sri)(?:\.|\s+)/, "").split(/[^a-z0-9]+/).filter(token => token.length >= 4);
const hasLongSharedNameFragment = (first: string, second: string) => {
  const shortest = first.length < second.length ? first : second;
  const longest = first.length < second.length ? second : first;
  for (let length = Math.min(12, shortest.length); length >= 7; length -= 1) {
    for (let start = 0; start <= shortest.length - length; start += 1) {
      if (longest.includes(shortest.slice(start, start + length))) return true;
    }
  }
  return false;
};

export function mergeFacultyPublicationData(
  directories: Record<string, import("../context/DataContext").DirectoryData>,
  records: FacultyPublicationRecord[]
) {
  const updated = { ...directories };
  Object.entries(updated).forEach(([department, directory]) => {
    const departmentRecords = records.filter(record => record.department === department);
    const attach = (member: import("../context/DataContext").FacultyMember) => {
      if (!member.name || member.publicationDetails?.length) return member;
      const expected = normalizeName(member.name);
      let matches = departmentRecords.filter(record => normalizeName(record.facultyName) === expected);
      if (!matches.length) {
        const expectedTokens = facultyNameTokens(member.name);
        const scores = new Map<string, number>();
        departmentRecords.forEach(record => {
          const candidate = normalizeName(record.facultyName);
          const sharedTokens = facultyNameTokens(record.facultyName).filter(token => expectedTokens.includes(token));
          const score = sharedTokens.length * 10 + (hasLongSharedNameFragment(expected, candidate) ? 1 : 0);
          if (score > 0) scores.set(record.facultyName, Math.max(score, scores.get(record.facultyName) || 0));
        });
        const bestScore = Math.max(0, ...scores.values());
        const bestNames = [...scores].filter(([, score]) => score === bestScore && score > 0).map(([name]) => name);
        if (bestNames.length === 1) matches = departmentRecords.filter(record => record.facultyName === bestNames[0]);
      }
      if (!matches.length) return member;
      return {
        ...member,
        publicationDetails: matches.map(record => ({ "Faculty Name": record.facultyName, ...record.details }))
      };
    };
    updated[department] = { ...directory, hod: attach(directory.hod), others: directory.others.map(attach) };
  });
  return updated;
}
